extension AnalyticsValues.Count {
    public init(bucketing value: Int) {
        if value <= 1 { self = ._1; return }
        if value <= 5 { self = ._2_5; return }
        if value <= 20 { self = ._6_20; return }
        if value <= 100 { self = ._21_100; return }
        self = ._101_plus
    }
}

extension AnalyticsValues.CallDuration {
    public init(bucketing value: Int) {
        if value <= 9 { self = .under10s; return }
        if value <= 59 { self = ._10s_1m; return }
        if value <= 299 { self = ._1m_5m; return }
        if value <= 1799 { self = ._5m_30m; return }
        self = ._30m_plus
    }
}

